1	/**
2	 * Agent activation loop.
3	 *
4	 * Drives the scan → claim → run cycle on a configurable interval.
5	 * All real I/O (sleep, the cycle itself) is injectable so tests can run
6	 * synchronously with recorded side-effects.
7	 *
8	 * Behaviour controlled by idle_sleep_seconds:
9	 *   0   → single-shot mode: run one cycle and return.
10	 *         Suitable for external schedulers (K8s CronJob, systemd timer).
11	 *   >0  → continuous mode: run cycles indefinitely, sleeping between them.
12	 *         Sleep is applied after every cycle — whether the cycle ran a task
13	 *         or found nothing (idle).
14	 */
15	
16	import type { AgentConfig } from "../config/validate-agent-yaml.js";
17	import type { SchedulerPort } from "@workflow/runtime-abi";
18	
19	/** Result returned by one activation cycle. */
20	export type CycleOutcome = "ran_task" | "idle";
21	
22	export interface AgentLoopOptions {
23	  config: AgentConfig;
24	  /** Execute one activation cycle. Must never throw — catch and return "idle" on error. */
25	  runCycle: () => Promise<CycleOutcome>;
26	  emit: (event: Record<string, unknown>) => void;
27	  /** Pause execution for ms milliseconds. Default: setTimeout-based. Injectable for tests. */
28	  sleep?: (ms: number) => Promise<void>;
29	  /**
30	   * SchedulerPort adapter — when provided, its sleep() method is used in
31	   * preference to the `sleep` function above. Allows the profile to control
32	   * cycle cadence via the port interface.
33	   */
34	  scheduler?: SchedulerPort;
35	}
36	
37	const defaultSleep = (ms: number): Promise<void> =>
38	  new Promise((resolve) => setTimeout(resolve, ms));
39	
40	/**
41	 * Run the agent activation loop.
42	 *
43	 * Returns only when:
44	 *   - single-shot mode (idle_sleep_seconds === 0): after one cycle.
45	 *   - In continuous mode: never (infinite loop — caller is responsible for
46	 *     process lifecycle).
47	 */
48	export async function runAgentLoop(opts: AgentLoopOptions): Promise<void> {
49	  const { config, runCycle, emit, scheduler } = opts;
50	  const sleep = scheduler
51	    ? (ms: number) => scheduler.sleep(ms)
52	    : (opts.sleep ?? defaultSleep);
53	  const sleepMs = (config.idle_sleep_seconds ?? 60) * 1000;
54	
55	  if (sleepMs === 0) {
56	    // Single-shot mode: one cycle, then return so main() can exit(0).
57	    await runCycle();
58	    return;
59	  }
60	
61	  // Continuous mode: cycle indefinitely with inter-cycle sleep.
62	  while (true) {
63	    const outcome = await runCycle();
64	
65	    if (outcome === "idle") {
66	      emit({ type: "activation_idle", sleep_ms: sleepMs });
67	    } else {
68	      emit({ type: "activation_complete", sleep_ms: sleepMs });
69	    }
70	
71	    await sleep(sleepMs);
72	  }
73	}
