1	/**
2	 * Tests for poll/agent-loop.ts
3	 *
4	 * Covers:
5	 *   - single-shot mode (idle_sleep_seconds === 0): runs exactly one cycle, no sleep
6	 *   - continuous mode (idle_sleep_seconds > 0): cycles with sleep between each
7	 *   - idle cycle emits activation_idle with sleep_ms
8	 *   - ran_task cycle emits activation_complete with sleep_ms
9	 *   - post-task sleep: sleep is applied after a successful task run (same as idle sleep)
10	 *   - injectable sleep: tests run synchronously by resolving immediately
11	 */
12	
13	import { describe, it, expect } from "vitest";
14	import { runAgentLoop, type CycleOutcome } from "../src/poll/agent-loop.js";
15	import type { AgentConfig } from "../src/config/validate-agent-yaml.js";
16	
17	// ── Helpers ───────────────────────────────────────────────────────────────────
18	
19	function makeConfig(idle_sleep_seconds: number | undefined): AgentConfig {
20	  return {
21	    watches: ["git@github.com:org/workspace.git"],
22	    enabled: true,
23	    jitter_max_seconds: 0,
24	    budget: { max_tokens_per_task: 1000, max_iterations: 5 },
25	    log_sink: { enabled: false },
26	    idle_sleep_seconds,
27	  };
28	}
29	
30	function makeImmediateSleep(): { sleep: (ms: number) => Promise<void>; calls: number[] } {
31	  const calls: number[] = [];
32	  return {
33	    sleep: (ms: number) => {
34	      calls.push(ms);
35	      return Promise.resolve();
36	    },
37	    calls,
38	  };
39	}
40	
41	function makeLimitedCycle(
42	  outcomes: CycleOutcome[],
43	  onExhausted?: () => never,
44	): { runCycle: () => Promise<CycleOutcome>; callCount: number } {
45	  let callCount = 0;
46	  const state = { callCount };
47	  return {
48	    runCycle: async () => {
49	      state.callCount++;
50	      callCount = state.callCount;
51	      const outcome = outcomes[callCount - 1];
52	      if (outcome === undefined) {
53	        if (onExhausted) onExhausted();
54	        throw new Error("runCycle called more times than expected");
55	      }
56	      return outcome;
57	    },
58	    get callCount() {
59	      return callCount;
60	    },
61	  };
62	}
63	
64	// ── Single-shot mode ──────────────────────────────────────────────────────────
65	
66	describe("runAgentLoop — single-shot mode (idle_sleep_seconds === 0)", () => {
67	  it("runs exactly one cycle and returns without sleeping", async () => {
68	    const config = makeConfig(0);
69	    const { sleep, calls } = makeImmediateSleep();
70	    let cycleCount = 0;
71	
72	    await runAgentLoop({
73	      config,
74	      runCycle: async () => { cycleCount++; return "idle"; },
75	      emit: () => {},
76	      sleep,
77	    });
78	
79	    expect(cycleCount).toBe(1);
80	    expect(calls).toHaveLength(0); // no sleep in single-shot mode
81	  });
82	
83	  it("runs exactly one cycle even when cycle returns ran_task", async () => {
84	    const config = makeConfig(0);
85	    const { sleep, calls } = makeImmediateSleep();
86	    let cycleCount = 0;
87	
88	    await runAgentLoop({
89	      config,
90	      runCycle: async () => { cycleCount++; return "ran_task"; },
91	      emit: () => {},
92	      sleep,
93	    });
94	
95	    expect(cycleCount).toBe(1);
96	    expect(calls).toHaveLength(0);
97	  });
98	
99	  it("does not emit activation_idle or activation_complete in single-shot mode", async () => {
100	    const config = makeConfig(0);
101	    const events: Record<string, unknown>[] = [];
102	
103	    await runAgentLoop({
104	      config,
105	      runCycle: async () => "idle",
106	      emit: (e) => events.push(e),
107	      sleep: async () => {},
108	    });
109	
110	    const types = events.map((e) => e["type"]);
111	    expect(types).not.toContain("activation_idle");
112	    expect(types).not.toContain("activation_complete");
113	  });
114	});
115	
116	// ── Continuous mode ───────────────────────────────────────────────────────────
117	
118	describe("runAgentLoop — continuous mode (idle_sleep_seconds > 0)", () => {
119	  it("sleeps after an idle cycle", async () => {
120	    const config = makeConfig(30); // 30s → 30000ms
121	    const { sleep, calls } = makeImmediateSleep();
122	    let cycleCount = 0;
123	
124	    // Run 3 cycles then abort by throwing to break the while(true) loop.
125	    await expect(
126	      runAgentLoop({
127	        config,
128	        runCycle: async () => {
129	          cycleCount++;
130	          if (cycleCount >= 3) throw new Error("stop");
131	          return "idle";
132	        },
133	        emit: () => {},
134	        sleep,
135	      }),
136	    ).rejects.toThrow("stop");
137	
138	    // Sleep should have been called twice (after cycle 1 and cycle 2).
139	    expect(calls).toHaveLength(2);
140	    expect(calls[0]).toBe(30_000);
141	    expect(calls[1]).toBe(30_000);
142	  });
143	
144	  it("sleeps after a ran_task cycle (post-task sleep)", async () => {
145	    const config = makeConfig(60); // 60s → 60000ms
146	    const { sleep, calls } = makeImmediateSleep();
147	    let cycleCount = 0;
148	
149	    await expect(
150	      runAgentLoop({
151	        config,
152	        runCycle: async () => {
153	          cycleCount++;
154	          if (cycleCount >= 2) throw new Error("stop");
155	          return "ran_task";
156	        },
157	        emit: () => {},
158	        sleep,
159	      }),
160	    ).rejects.toThrow("stop");
161	
162	    expect(calls).toHaveLength(1);
163	    expect(calls[0]).toBe(60_000);
164	  });
165	
166	  it("emits activation_idle when cycle returns idle", async () => {
167	    const config = makeConfig(10);
168	    const events: Record<string, unknown>[] = [];
169	    let cycleCount = 0;
170	
171	    await expect(
172	      runAgentLoop({
173	        config,
174	        runCycle: async () => {
175	          cycleCount++;
176	          if (cycleCount >= 2) throw new Error("stop");
177	          return "idle";
178	        },
179	        emit: (e) => events.push(e),
180	        sleep: async () => {},
181	      }),
182	    ).rejects.toThrow("stop");
183	
184	    const idleEvent = events.find((e) => e["type"] === "activation_idle");
185	    expect(idleEvent).toBeDefined();
186	    expect(idleEvent!["sleep_ms"]).toBe(10_000);
187	  });
188	
189	  it("emits activation_complete when cycle returns ran_task", async () => {
190	    const config = makeConfig(10);
191	    const events: Record<string, unknown>[] = [];
192	    let cycleCount = 0;
193	
194	    await expect(
195	      runAgentLoop({
196	        config,
197	        runCycle: async () => {
198	          cycleCount++;
199	          if (cycleCount >= 2) throw new Error("stop");
200	          return "ran_task";
201	        },
202	        emit: (e) => events.push(e),
203	        sleep: async () => {},
204	      }),
205	    ).rejects.toThrow("stop");
206	
207	    const doneEvent = events.find((e) => e["type"] === "activation_complete");
208	    expect(doneEvent).toBeDefined();
209	    expect(doneEvent!["sleep_ms"]).toBe(10_000);
210	  });
211	
212	  it("uses 60s default when idle_sleep_seconds is undefined", async () => {
213	    const config = makeConfig(undefined); // should default to 60
214	    const { sleep, calls } = makeImmediateSleep();
215	    let cycleCount = 0;
216	
217	    await expect(
218	      runAgentLoop({
219	        config,
220	        runCycle: async () => {
221	          cycleCount++;
222	          if (cycleCount >= 2) throw new Error("stop");
223	          return "idle";
224	        },
225	        emit: () => {},
226	        sleep,
227	      }),
228	    ).rejects.toThrow("stop");
229	
230	    expect(calls[0]).toBe(60_000);
231	  });
232	
233	  it("alternates idle and ran_task outcomes correctly", async () => {
234	    const config = makeConfig(5);
235	    const events: Record<string, unknown>[] = [];
236	    const outcomes: CycleOutcome[] = ["idle", "ran_task", "idle"];
237	    let idx = 0;
238	
239	    await expect(
240	      runAgentLoop({
241	        config,
242	        runCycle: async () => {
243	          const outcome = outcomes[idx++];
244	          if (outcome === undefined) throw new Error("stop");
245	          return outcome;
246	        },
247	        emit: (e) => events.push(e),
248	        sleep: async () => {},
249	      }),
250	    ).rejects.toThrow("stop");
251	
252	    const types = events.map((e) => e["type"]);
253	    expect(types).toEqual(["activation_idle", "activation_complete", "activation_idle"]);
254	  });
255	});
