1	/**
2	 * Orchestrator side-effect dispatcher.
3	 *
4	 * Translates an ExecutorResult into the correct set of side effects:
5	 *   in_review  → mutate task YAML to in_review, append log
6	 *                (pr_url recorded from result.pr_url if present — executor opened it)
7	 *   blocked    → mutate task YAML to blocked, append log
8	 *                (pr_url recorded from result.pr_url if present — draft PR documents failure)
9	 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
10	 *
11	 * Revised D5: the executor owns impl-PR creation (via /pr-create skill).
12	 * The orchestrator no longer opens impl PRs — it only records the pr_url
13	 * reported by the executor in result.json.
14	 *
15	 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
16	 * verify the resulting task state without running the full bootstrap + poll loop.
17	 */
18	
19	import type { ExecutorResult } from "@workflow/runtime-abi";
20	import { mutateTaskYaml } from "./mutate-task-yaml.js";
21	import { appendLogEntry } from "./append-log.js";
22	
23	export interface DispatchExecutorResultOpts {
24	  result: ExecutorResult;
25	  workspaceRoot: string;
26	  featureId: string;
27	  taskId: string;
28	  taskBranch: string;
29	  taskTitle: string;
30	  taskRepoUrl: string;
31	  taskBaseBranch: string;
32	  githubToken: string;
33	  gitAuthorEmail: string;
34	  gitAuthorName?: string;
35	  sshKeyPath?: string;
36	  emit: (event: Record<string, unknown>) => void;
37	}
38	
39	/**
40	 * Apply the side effects that correspond to an executor result.
41	 * Called by the orchestrator polling loop after adapter.run() returns.
42	 * Non-throwing: individual side-effect errors are emitted as events but do
43	 * not propagate — the cycle continues normally.
44	 */
45	export async function dispatchExecutorResult(
46	  opts: DispatchExecutorResultOpts,
47	): Promise<void> {
48	  const {
49	    result,
50	    workspaceRoot,
51	    featureId,
52	    taskId,
53	    taskBranch,
54	    gitAuthorEmail,
55	    gitAuthorName,
56	    sshKeyPath,
57	    emit,
58	  } = opts;
59	
60	  // pr_url from result.json — set by executor when it opened a PR.
61	  // Present on any terminal_status when commits were pushed and a PR was opened.
62	  const prUrl = result.pr_url;
63	
64	  if (result.terminal_status === "in_review") {
65	    if (prUrl) {
66	      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
67	    }
68	
69	    const mutateErr = mutateTaskYaml({
70	      workspaceRoot,
71	      featureId,
72	      taskId,
73	      taskBranch,
74	      result,
75	      prUrl,
