1	/**
2	 * local-subprocess profile factory.
3	 *
4	 * Bundles the Wave-3 adapter set into a RuntimePorts instance for the
5	 * single-container, single-process topology: orchestrator and executor
6	 * run as child processes inside the same image.
7	 *
8	 * Adapter set:
9	 *   ExecutorPort         → SubProcessAdapterW2     (blocks in Wave 2; async in Wave 3/T5)
10	 *   CompletionBrokerPort → InMemoryBrokerAdapter   (Wave 3 / T3 — embedded HTTP receiver)
11	 *   BriefingTransport    → LocalFileBriefingAdapter
12	 *   WorkflowState        → GitWorkflowStateAdapter
13	 *   Credential           → EnvCredentialAdapter
14	 *   WorkspacePull        → GitClonePullAdapter
15	 *   EventEmitter         → StdoutJsonEmitter
16	 *   Scheduler            → SimpleSleepScheduler
17	 *   Clock                → RealClock
18	 */
19	
20	import type { RuntimePorts } from "../runtime-ports.js";
21	import { SubProcessAdapterW2, type SubProcessAdapterOpts } from "../adapters/executor/subprocess.js";
22	import { InMemoryBrokerAdapter, type InMemoryBrokerAdapterOpts } from "../adapters/broker/in-memory.js";
23	import { LocalFileBriefingAdapter } from "../adapters/briefing/local-file.js";
24	import { GitWorkflowStateAdapter } from "../adapters/workflow-state/git.js";
25	import { EnvCredentialAdapter } from "../adapters/credential/env.js";
26	import { GitClonePullAdapter } from "../adapters/workspace-pull/git-clone-pull.js";
27	import { StdoutJsonEmitter } from "../adapters/emitter/stdout-json.js";
28	import { SimpleSleepScheduler } from "../adapters/scheduler/simple-sleep.js";
29	import { RealClock } from "../adapters/clock/real.js";
30	
31	export interface LocalSubprocessProfileOpts {
32	  /** Options forwarded to SubProcessAdapterW2. */
33	  executor?: SubProcessAdapterOpts;
34	  /** Options forwarded to InMemoryBrokerAdapter. */
35	  broker?: InMemoryBrokerAdapterOpts;
36	  /** Git identity for WorkflowStatePort operations. */
37	  gitAuthorEmail: string;
38	  gitAuthorName?: string;
39	  sshKeyPath?: string;
40	}
41	
42	/** The broker is part of the profile bundle so callers can call start()/stop(). */
43	export interface LocalSubprocessProfileBundle extends RuntimePorts {
44	  broker: InMemoryBrokerAdapter;
45	}
46	
47	/**
48	 * Create a RuntimePorts bundle wired for the local-subprocess profile.
49	 *
50	 * Callers must call `bundle.broker.start()` after creation to bind the HTTP
51	 * receiver port, and `bundle.broker.stop()` on graceful shutdown.
52	 *
53	 * The broker is wired into the executor so that SubProcessAdapterW2.submit()
54	 * can call broker.register() before spawning the runner wrapper (T5 Wave-3).
55	 * The orchestrator then passes callbackUrl = broker.getCallbackUrl() in the
56	 * ExecutorPortInput when submitting tasks.
57	 *
58	 * Example:
59	 *   const bundle = createLocalSubprocessProfile({ gitAuthorEmail: '...' });
60	 *   const brokerPort = await bundle.broker.start();
61	 *   // pass bundle to orchestrator concerns...
62	 *   await bundle.broker.stop();
63	 */
64	export function createLocalSubprocessProfile(
65	  opts: LocalSubprocessProfileOpts,
66	): LocalSubprocessProfileBundle {
67	  const broker = new InMemoryBrokerAdapter(opts.broker);
68	  const executor = new SubProcessAdapterW2({ ...opts.executor, broker });
69	  return {
70	    executor,
71	    broker,
72	    briefing: new LocalFileBriefingAdapter(),
73	    workflowState: new GitWorkflowStateAdapter({
74	      gitAuthorEmail: opts.gitAuthorEmail,
75	      gitAuthorName: opts.gitAuthorName,
76	      sshKeyPath: opts.sshKeyPath,
77	    }),
78	    credential: new EnvCredentialAdapter(),
79	    workspacePull: new GitClonePullAdapter(),
80	    emitter: new StdoutJsonEmitter(),
81	    scheduler: new SimpleSleepScheduler(),
82	    clock: new RealClock(),
83	  };
84	}
