1	/**
2	 * Orchestrator main entry point.
3	 *
4	 * Lifecycle:
5	 *   bootstrap (once) → polling loop:
6	 *     pull workspaces → eligibility → claim → briefing → adapter.run →
7	 *     side-effects → sleep → repeat
8	 *
9	 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
10	 *   0   → single-shot mode: one cycle then exit
11	 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
12	 *
13	 * Exit codes:
14	 *   0  normal exit
15	 *   2  agent.yaml invalid
16	 *   3  git clone/pull failed (bootstrap only)
17	 *   4  unexpected fatal error
18	 */
19	
20	import { existsSync, readFileSync, writeFileSync } from "node:fs";
21	import { join } from "node:path";
22	import { tmpdir } from "node:os";
23	import { execSync } from "node:child_process";
24	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
25	import { runBootstrap } from "./bootstrap/bootstrap.js";
26	import { resolveSSHKey } from "./resolve-ssh-key.js";
27	import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName } from "./paths.js";
28	import { findEligibleTasks } from "./eligibility/match.js";
29	import { claimTask } from "./claim/claim-task.js";
30	import { openWorkspacePr } from "./claim/open-workspace-pr.js";
31	import type { Task, TaskLogEntry } from "./types/task.js";
32	import { generateBriefing } from "./briefing/agent-context.js";
33	import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
34	import { resolveModel } from "./config/resolve-model-policy.js";
35	import { parseModelOverrides } from "./config/parse-model-overrides.js";
36	import {
37	  resolveRepoLocalPath,
38	  resolveRepoBaseBranch,
39	  resolveRepoGitUrl,
40	  loadWorkspaceModelPolicy,
41	  parseManagementRepoCoords,
42	} from "./config/workspace-config.js";
43	import { pullWorkspaces } from "./poll/pull-workspaces.js";
44	import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
45	import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
46	import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
47	import { handleDraftReviews } from "./pr-response/dispatch-draft-review.js";
48	import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
49	import type { ExecutorPortInput } from "@workflow/runtime-abi";
50	import { dispatchExecutorResult } from "./side-effects/dispatch.js";
51	import { buildGitEnv } from "./git-env.js";
52	import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
53	import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
54	import type { RuntimePorts } from "./runtime-ports.js";
55	import { SubProcessAdapterW2 } from "./adapters/executor/subprocess.js";
56	
57	// ── Helpers ───────────────────────────────────────────────────────────────────
58	
59	function requireEnv(name: string): string {
60	  const val = process.env[name];
61	  if (!val) throw new Error(`Required environment variable ${name} is not set`);
62	  return val;
63	}
64	
65	function extractRepoName(url: string): string {
66	  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
67	  return match?.[1] ?? url;
68	}
69	
70	/** Emit a structured JSON event via the profile's EventEmitterPort. */
71	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
72	  return (event: Record<string, unknown>) => {
73	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
74	    ports.emitter.emit(type ?? "event", data);
75	  };
76	}
77	
78	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
79	  const task = parseYaml(
80	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
81	  ) as { repo: string };
82	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
83	  return task.repo;
84	}
85	
86	interface TaskContext {
87	  taskRepoRoot: string;
88	  taskRepoUrl: string;
89	  taskBaseBranch: string;
90	  implementationModel: string;
91	}
92	
93	function resolveTaskContext(
94	  workspaceLocalPath: string,
95	  featureId: string,
96	  task: Task,
97	): TaskContext {
98	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
99	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
100	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
101	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
102	
103	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
104	  let taskModelOverrides = {};
105	  try {
106	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
107	  } catch { /* non-fatal */ }
108	
109	  const implementationModel = resolveModel(
110	    workspaceModelPolicy,
111	    taskModelOverrides,
112	    "implementation",
113	    task.id,
114	  );
115	
116	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
117	}
118	
119	/**
120	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
121	 * Commits and pushes to the task branch. Throws on error.
122	 */
123	function writeRagPreFlight(
124	  workspaceRoot: string,
125	  featureId: string,
126	  taskId: string,
127	  taskBranch: string,
128	  gitAuthorEmail: string,
129	  gitAuthorName: string,
130	  sshKeyPath: string | undefined,
131	  ragPreFlight: { query: string; injected: boolean; summary: string },
132	): void {
133	  const now = new Date().toISOString();
134	  const entry: TaskLogEntry = {
135	    action: "rag_pre_flight",
136	    by: gitAuthorEmail,
137	    at: now,
138	    rag_context_injected: ragPreFlight.injected,
139	    rag_summary: ragPreFlight.summary,
140	    rag_query: ragPreFlight.query,
141	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
142	  };
143	
144	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
145	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
146	  task.log.push(entry);
147	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
148	
149	  const relPath = taskYamlRelPath(featureId, taskId);
150	  const gitOpts = {
151	    cwd: workspaceRoot,
152	    encoding: "utf-8" as const,
153	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
154	    timeout: 30_000,
155	    stdio: "pipe" as const,
156	  };
157	  execSync(`git add "${relPath}"`, gitOpts);
158	  execSync(
159	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
160	    gitOpts,
161	  );
162	  execSync(`git push origin "${taskBranch}"`, gitOpts);
163	}
164	
165	// ── Main ──────────────────────────────────────────────────────────────────────
166	
167	async function main(): Promise<number> {
168	  let agentYamlPath: string;
169	  let workflowLocalPath: string;
170	  let workspacesRoot: string;
171	  let gitAuthorEmail: string;
172	
173	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
174	  const bootstrapEmit = (event: Record<string, unknown>) => {
175	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
176	  };
177	
178	  try {
179	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
180	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
181	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
182	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
183	  } catch (e) {
184	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
185	    return 4;
186	  }
187	
188	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
189	
190	  const sshResolution = resolveSSHKey(process.env);
191	  const sshKeyPath = sshResolution.sshKeyPath;
192	
193	  // ── Create the local-subprocess profile ──────────────────────────────────────
194	  // The profile bundles all port adapters for the current deployment topology.
195	  // Switching profiles at startup is how new infra is added without core changes.
196	  const ports = createLocalSubprocessProfile({
197	    gitAuthorEmail,
198	    gitAuthorName,
199	    sshKeyPath,
200	  });
201	
202	  // T3: Start the embedded broker's HTTP receiver so runners can POST callbacks.
203	  // The broker is dormant (not yet wired into claims) until T5/T6 ship, but the
204	  // port must be bound at startup so the port file is present for spawn code.
205	  const brokerPort = await ports.broker.start();
206	
207	  const emit = makeEmit(ports);
208	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
209	
210	  if (sshResolution.warned) {
211	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
212	  }
213	
214	  const bootstrapResult = await runBootstrap({
215	    agentYamlPath,
216	    workflowLocalPath,
217	    workflowUrl: process.env.WORKFLOW_URL,
218	    workspacesRoot,
219	    sshKeyPath,
220	  });
221	
222	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
223	
224	  const config = bootstrapResult.config!;
225	  const githubToken = process.env.GITHUB_TOKEN ?? "";
226	  if (!githubToken) emit({ type: "warn_no_github_token" });
227	
228	  let lastPrPollAt: number | null = null;
229	
230	  async function runOneCycle(): Promise<CycleOutcome> {
231	    const pullResults = pullWorkspaces({
232	      watchUrls: config.watches,
233	      sshKeyPath,
234	      workspacesRoot,
235	      workflowUrl: process.env.WORKFLOW_URL,
236	      workflowLocalPath,
237	      emit,
238	    });
239	
240	    const haltedUrls = new Set(
241	      pullResults
242	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
243	        .map((r) => r.url),
244	    );
245	
246	    let outcome: CycleOutcome = "idle";
247	    const pulledWorkspaceRoots: string[] = [];
248	
249	    outerLoop:
250	    for (const watchUrl of config.watches) {
251	      if (haltedUrls.has(watchUrl)) continue;
252	
253	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
254	      pulledWorkspaceRoots.push(workspaceLocalPath);
255	
256	      if (!existsSync(workspaceLocalPath)) {
257	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
258	        continue;
259	      }
260	
261	      let eligibleTasks;
262	      try {
263	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
264	      } catch (e) {
265	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
266	        continue;
267	      }
268	
269	      if (eligibleTasks.length === 0) {
270	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
271	        continue;
272	      }
273	
274	      for (const { task, featureId } of eligibleTasks) {
275	        const claimResult = await claimTask({
276	          workspaceRoot: workspaceLocalPath,
277	          taskId: task.id,
278	          featureId,
279	          gitAuthorEmail,
280	          gitAuthorName,
281	          sshKeyPath,
282	          jitterMaxSeconds: config.jitter_max_seconds,
283	        });
284	
285	        const taskBranch = taskBranchName(featureId, task.id);
286	
287	        if (!claimResult.won) {
288	          if (claimResult.reason !== "branch_blocked_recovery") {
289	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
290	            continue;
291	          }
292	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
293	        } else {
294	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
295	        }
296	
297	        // ── Open management-repo PR ───────────────────────────────────────────
298	        if (githubToken) {
299	          try {
300	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
301	            await openWorkspacePr({
302	              workspaceRoot: workspaceLocalPath,
303	              featureId,
304	              taskId: task.id,
305	              branch: taskBranch,
306	              baseBranch: mgmtCoords.baseBranch,
307	              githubToken,
308	              repoOwner: mgmtCoords.owner,
309	              repoName: mgmtCoords.repo,
310	              gitAuthorEmail,
311	              gitAuthorName,
312	              sshKeyPath,
313	            });
314	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
315	          } catch (e) {
316	            const stderr = (e as { stderr?: Buffer | string }).stderr;
317	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
318	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
319	          }
320	        }
321	
322	        // ── Resolve model + task repo ────────────────────────────────────────
323	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
324	          resolveTaskContext(workspaceLocalPath, featureId, task);
325	
326	        // ── RAG pre-flight ───────────────────────────────────────────────────
327	        const mcpRagUrl = process.env.MCP_RAG_URL;
328	        const workspaceYaml = parseYaml(
329	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
330	        ) as { workspace_id: string };
331	        const ragQuery = `${task.title} ${featureId}`;
332	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
333	
334	        try {
335	          writeRagPreFlight(
336	            workspaceLocalPath,
337	            featureId,
338	            task.id,
339	            taskBranch,
340	            gitAuthorEmail,
341	            gitAuthorName,
342	            sshKeyPath,
343	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
344	          );
345	        } catch (e) {
346	          const details = String(e);
347	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
348	          mutateTaskYaml({
349	            workspaceRoot: workspaceLocalPath,
350	            featureId,
351	            taskId: task.id,
352	            taskBranch,
353	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
354	            gitAuthorEmail,
355	            gitAuthorName,
356	            sshKeyPath,
357	          });
358	          continue;
359	        }
360	
361	        // ── Generate briefing ────────────────────────────────────────────────
362	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
363	        const baseContext = generateBriefing({
364	          taskId: task.id,
365	          featureId,
366	          taskTitle: task.title,
367	          taskBranch,
368	          taskRepo: task.repo,
369	          taskRepoRoot,
370	          workspaceRoot: workspaceLocalPath,
371	          gitAuthorEmail,
372	          gitAuthorName,
373	          implementationModel,
374	          resultPath,
375	        });
376	        const briefingContent = ragPreFlight.block
377	          ? `${baseContext}\n\n${ragPreFlight.block}`
378	          : baseContext;
379	
380	        // ── Write briefing via BriefingTransportPort ─────────────────────────
381	        // Use taskId as the briefing handle so the file path matches the
382	        // existing briefing-{taskId}/briefing.md convention.
383	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
384	
385	        // ── Build ExecutorPortInput ──────────────────────────────────────────
386	        // callbackUrl and nonce are Wave-3 broker fields; the NullBrokerAdapter
387	        // ignores them in Wave 2.
388	        const execInput: ExecutorPortInput = {
389	          taskId: task.id,
390	          featureId,
391	          workspaceId: workspaceYaml.workspace_id,
392	          taskRepoUrl,
393	          taskRepoBranch: taskBranch,
394	          taskRepoPath: taskRepoRoot,
395	          briefingPath,
396	          resultPath,
397	          budgetTokens: config.budget.max_tokens_per_task,
398	          sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
399	          githubToken,
400	          callbackUrl: "",
401	          nonce: "",
402	        };
403	
404	        // ── Run executor via ExecutorPort ────────────────────────────────────
405	        // Wave 2: submit() still blocks internally (preserves today's flow).
406	        // extraEnv is per-task so a fresh SubProcessAdapterW2 is created here;
407	        // other ports (emitter, scheduler, etc.) are reused from the profile.
408	        const perTaskExecutor = new SubProcessAdapterW2({
409	          extraEnv: {
410	            WORKSPACE_ROOT: workspaceLocalPath,
411	            TASK_BRANCH: taskBranch,
412	            GIT_AUTHOR_EMAIL: gitAuthorEmail,
413	            GIT_AUTHOR_NAME: gitAuthorName,
414	            WORKFLOW_LOCAL_PATH: workflowLocalPath,
415	            MAX_TURNS: String(config.budget.max_iterations),
416	            LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
417	            ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
418	            ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
419	              ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
420	              : {}),
421	          },
422	        });
423	
424	        const execHandle = await perTaskExecutor.submit(execInput);
425	        const execResult = await perTaskExecutor.readResult(execHandle);
426	
427	        emit({
428	          type: "executor_result",
429	          task_id: task.id,
430	          feature_id: featureId,
431	          terminal_status: execResult.terminal_status,
432	        });
433	
434	        // ── Side-effects ─────────────────────────────────────────────────────
435	        await dispatchExecutorResult({
436	          result: execResult,
437	          workspaceRoot: workspaceLocalPath,
438	          featureId,
439	          taskId: task.id,
440	          taskBranch,
441	          taskTitle: task.title,
442	          taskRepoUrl,
443	          taskBaseBranch,
444	          githubToken,
445	          gitAuthorEmail,
446	          gitAuthorName,
447	          sshKeyPath,
448	          emit,
449	        });
450	
451	        emit({ type: "task_run_complete", task_id: task.id, feature_id: featureId, outcome: execResult.terminal_status });
452	        outcome = "ran_task";
453	        break outerLoop;
454	      }
455	    }
456	
457	    // ── In-review PR poll ─────────────────────────────────────────────────────
458	    if (githubToken) {
459	      const prPollIntervalMs =
460	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
461	      const now = Date.now();
462	
463	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
464	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
465	        try {
466	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
467	            workspaceRoots: pulledWorkspaceRoots,
468	            githubToken,
469	            emit,
470	          });
471	
472	          for (const wsRoot of pulledWorkspaceRoots) {
473	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
474	            if (wsResults.some((r) => r.mergeable === false)) {
475	              await handleMergeConflicts({
476	                prResults: wsResults,
477	                workspaceRoot: wsRoot,
478	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
479	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
480	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
481	                gitAuthorEmail,
482	                gitAuthorName,
483	                sshKeyPath,
484	                emit,
485	              });
486	            }
487	          }
488	
489	          for (const wsRoot of pulledWorkspaceRoots) {
490	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
491	            if (wsResults.some((r) => r.hasOpenComments === true)) {
492	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
493	              await handleDraftReviews({
494	                prResults: wsResults,
495	                workspaceRoot: wsRoot,
496	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
497	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
498	                resolveImplementationModel: (fId, tId) => {
499	                  try {
500	                    const tMdPath = join(wsRoot, "docs", "features", fId, "tasks.md");
501	                    const overrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), tId);
502	                    return resolveModel(wsModelPolicy, overrides, "implementation", tId);
503	                  } catch {
504	                    return resolveModel(wsModelPolicy, {}, "implementation", tId);
505	                  }
506	                },
507	                gitAuthorEmail,
508	                gitAuthorName,
509	                sshKeyPath,
510	                workflowLocalPath,
511	                maxTurns: config.budget.max_iterations,
512	                maxTokens: config.budget.max_tokens_per_task,
513	                logSinkEnabled: config.log_sink.enabled,
514	                workspaceId: (() => {
515	                  try {
516	                    return (parseYaml(readFileSync(workspaceYamlPath(wsRoot), "utf-8")) as { workspace_id: string }).workspace_id ?? "";
517	                  } catch { return ""; }
518	                })(),
519	                githubToken,
520	                resolveImplRepoUrl: (repoId) => resolveRepoGitUrl(wsRoot, repoId),
521	                emit,
522	              });
523	            }
524	          }
525	
526	          for (const wsRoot of pulledWorkspaceRoots) {
527	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
528	            if (wsResults.some((r) => r.merged === true)) {
529	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
530	              await handleMergedPrs({
531	                prResults: wsResults,
532	                workspaceRoot: wsRoot,
533	                mgmtRepoOwner: mgmtCoords.owner,
534	                mgmtRepoName: mgmtCoords.repo,
535	                mgmtBaseBranch: mgmtCoords.baseBranch,
536	                githubToken,
537	                gitAuthorEmail,
538	                gitAuthorName,
539	                sshKeyPath,
540	                emit,
541	              });
542	            }
543	          }
544	
545	          for (const wsRoot of pulledWorkspaceRoots) {
546	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
547	            if (wsRecoveries.length > 0) {
548	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
549	              await handleWorkspacePrRecoveries({
550	                recoveries: wsRecoveries,
551	                mgmtRepoOwner: mgmtCoords.owner,
552	                mgmtRepoName: mgmtCoords.repo,
553	                mgmtBaseBranch: mgmtCoords.baseBranch,
554	                githubToken,
555	                gitAuthorEmail,
556	                gitAuthorName,
557	                sshKeyPath,
558	                emit,
559	              });
560	            }
561	          }
562	        } catch (e) {
563	          emit({ type: "in_review_poll_error", details: String(e) });
564	        }
565	      }
566	    }
567	
568	    return outcome;
569	  }
570	
571	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
572	  return 0;
573	}
574	
575	main()
576	  .then((code) => process.exit(code))
577	  .catch((e) => {
578	    try {
579	      console.log(JSON.stringify({
580	        type: "fatal_error",
581	        details: (e as Error).message ?? String(e),
582	        at: new Date().toISOString(),
583	      }));
584	    } catch { /* last resort */ }
585	    process.exit(4);
586	  });
