/**
 * Orchestrator side-effect dispatcher.
 *
 * Translates an ExecutorResult into the correct set of side effects:
 *   in_review  → mutate task YAML to in_review, append log
 *                (pr_url recorded from result.pr_url if present — executor opened it)
 *   blocked    → mutate task YAML to blocked, append log
 *                (pr_url recorded from result.pr_url if present — draft PR documents failure)
 *   failed     → mutate task YAML to blocked (executor_failed:*), append log
 *
 * Revised D5: the executor owns impl-PR creation (via /pr-create skill).
 * The orchestrator no longer opens impl PRs — it only records the pr_url
 * reported by the executor in result.json.
 *
 * Extracted from main.ts so seam tests can inject any ExecutorAdapter and
 * verify the resulting task state without running the full bootstrap + poll loop.
 */

import type { ExecutorResult } from "@workflow/runtime-abi";
import { mutateTaskYaml } from "./mutate-task-yaml.js";
import { appendLogEntry } from "./append-log.js";

export interface DispatchExecutorResultOpts {
  result: ExecutorResult;
  workspaceRoot: string;
  featureId: string;
  taskId: string;
  taskBranch: string;
  taskTitle: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

/**
 * Apply the side effects that correspond to an executor result.
 * Called by the orchestrator polling loop after adapter.run() returns.
 * Non-throwing: individual side-effect errors are emitted as events but do
 * not propagate — the cycle continues normally.
 */
export async function dispatchExecutorResult(
  opts: DispatchExecutorResultOpts,
): Promise<void> {
  const {
    result,
    workspaceRoot,
    featureId,
    taskId,
    taskBranch,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  // pr_url from result.json — set by executor when it opened a PR.
  // Present on any terminal_status when commits were pushed and a PR was opened.
  const prUrl = result.pr_url;

  if (result.terminal_status === "in_review") {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "in_review",
        by: gitAuthorEmail,
        note: prUrl ? `Implementation PR: ${prUrl}` : "Implementation complete.",
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  } else {
    if (prUrl) {
      emit({ type: "impl_pr_recorded", task_id: taskId, feature_id: featureId, pr_url: prUrl });
    }

    const mutateErr = mutateTaskYaml({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      result,
      prUrl,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (mutateErr) emit({ type: "mutate_task_yaml_failed", task_id: taskId, details: mutateErr });

    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "blocked",
        by: gitAuthorEmail,
        note: result.blocked_reason ?? "executor returned non-in_review status",
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });
    if (logErr) emit({ type: "append_log_failed", task_id: taskId, details: logErr });
  }
}

/**
 * RuntimePorts — the full set of port interfaces the orchestrator core depends on.
 *
 * A profile factory creates one RuntimePorts bundle at startup; the bundle is
 * then injected into the orchestrator concerns. The core never touches concrete
 * adapter classes — only this interface bundle.
 */

import type {
  ExecutorPort,
  CompletionBrokerPort,
  BriefingTransportPort,
  WorkflowStatePort,
  CredentialPort,
  WorkspacePullPort,
  EventEmitterPort,
  SchedulerPort,
  ClockPort,
} from "@workflow/runtime-abi";

export interface RuntimePorts {
  /** Spawn an executor; return a handle immediately (async in Wave 3+). */
  executor: ExecutorPort;

  /** Completion queue — in-flight registry + peek-and-lock drain. */
  broker: CompletionBrokerPort;

  /** Deliver briefings to executors. */
  briefing: BriefingTransportPort;

  /** Read/write workflow state (task YAMLs, logs). */
  workflowState: WorkflowStatePort;

  /** Provide credentials (GitHub token, SSH key path) to executors. */
  credential: CredentialPort;

  /** Materialize workspace repos (clone + pull). */
  workspacePull: WorkspacePullPort;

  /** Emit structured events / metrics. */
  emitter: EventEmitterPort;

  /** Control cycle cadence (sleep between cycles). */
  scheduler: SchedulerPort;

  /** Wall-clock time and sleep (mockable in tests). */
  clock: ClockPort;
}

