48	import type { ExecutorInput } from "@workflow/runtime-abi";
49	import { SubProcessAdapter } from "../src/adapter/spawn.js";
50	import { dispatchExecutorResult } from "../src/side-effects/dispatch.js";
51	
52	// ── Mock git for dispatch side-effects ────────────────────────────────────────
53	
54	vi.mock("node:child_process", async (importOriginal) => {
55	  const actual = await importOriginal<typeof import("node:child_process")>();
56	  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
