1	/**
2	 * T4: Draft-state comment resolution dispatch.
3	 *
4	 * When T2 reports `hasOpenComments: true` for an `in_review` task, this handler:
5	 *
6	 *   1. Claims the review work by appending a `review_started` log entry to
7	 *      the task YAML on the management-repo feature branch and pushing.
8	 *      First-push-wins: if the push is rejected, another agent claimed first.
9	 *
10	 *   2. Generates a review briefing that instructs Claude to execute the
11	 *      `respond-to-review` skill.
12	 *
13	 *   3. Invokes the Claude executor via SubProcessAdapter with that briefing.
14	 */
15	
16	import { execSync, spawnSync } from "node:child_process";
17	import { join } from "node:path";
18	import { tmpdir } from "node:os";
19	import type { Task } from "../types/task.js";
20	import type { PrStatusResult } from "../poll/check-in-review-prs.js";
21	import { buildGitEnv } from "../git-env.js";
22	import { SubProcessAdapter } from "../adapter/spawn.js";
23	import type { ExecutorInput } from "@workflow/runtime-abi";
24	import { taskYamlRelPath } from "../paths.js";
25	import { readTask, writeTask } from "../utils/task-yaml-io.js";
26	import { writeBriefing } from "../briefing/write-briefing.js";
27	import { preambleSection, identitySection, taskContextSection, modelSection, joinSections } from "../briefing/briefing-template.js";
28	
29	// ── Public types ──────────────────────────────────────────────────────────────
30	
31	export type DraftReviewOutcome =
32	  | "claim_lost"
33	  | "dispatched";
34	
35	export interface DispatchOneReviewOptions {
36	  workspaceRoot: string;
37	  featureId: string;
38	  taskId: string;
39	  taskBranch: string;
40	  implRepoRoot: string;
41	  /** SSH or HTTPS URL of the implementation repo. */
42	  implRepoUrl: string;
43	  gitAuthorEmail: string;
44	  gitAuthorName?: string;
45	  sshKeyPath?: string;
46	  workflowLocalPath: string;
47	  maxTurns: number;
48	  maxTokens: number;
49	  logSinkEnabled: boolean;
50	  implementationModel: string;
51	  workspaceId: string;
52	  githubToken: string;
53	  emit: (event: Record<string, unknown>) => void;
54	}
55	
56	export interface HandleDraftReviewsOptions {
57	  prResults: PrStatusResult[];
58	  workspaceRoot: string;
59	  resolveImplRepoRoot: (repoId: string) => string;
60	  resolveImplRepoUrl: (repoId: string) => string;
61	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
62	  resolveImplementationModel: (featureId: string, taskId: string) => string;
63	  gitAuthorEmail: string;
64	  gitAuthorName?: string;
65	  sshKeyPath?: string;
66	  workflowLocalPath: string;
67	  maxTurns: number;
68	  maxTokens: number;
69	  logSinkEnabled: boolean;
70	  workspaceId: string;
71	  githubToken: string;
72	  emit: (event: Record<string, unknown>) => void;
73	}
74	
75	// ── Internal helpers ──────────────────────────────────────────────────────────
76	
77	function generateReviewBriefing(opts: {
78	  taskId: string;
79	  featureId: string;
80	  taskTitle: string;
81	  taskBranch: string;
82	  taskRepo: string;
83	  taskRepoRoot: string;
84	  workspaceRoot: string;
85	  prUrl: string;
86	  gitAuthorEmail: string;
87	  gitAuthorName: string;
88	  implementationModel: string;
89	}): string {
90	  const {
91	    taskId, featureId, taskTitle, taskBranch, taskRepo, taskRepoRoot,
92	    workspaceRoot, prUrl, gitAuthorEmail, gitAuthorName, implementationModel,
93	  } = opts;
94	
95	  return joinSections(
96	    preambleSection(),
97	    identitySection({ gitAuthorEmail, gitAuthorName }),
98	    taskContextSection("Your claimed task", {
99	      taskId, featureId, taskTitle, taskBranch,
100	      taskRepo, taskRepoRoot, workspaceRoot, prUrl,
101	    }),
102	    [
103	      "## What you must do",
104	      "",
105	      "1. Read the following documents in order to understand the task context before reviewing:",
106	      `   a. \`${workspaceRoot}/docs/features/${featureId}/product-spec.md\` — original user requirements and business constraints`,
107	      `   b. \`${workspaceRoot}/docs/features/${featureId}/technical-design.md\` — implementation approach and architecture`,
108	      `   c. \`${workspaceRoot}/docs/features/${featureId}/tasks.md\` under heading \`## ${taskId} — ${taskTitle}\` — specific task scope and subtasks`,
109	      "2. Run `/respond-to-review` to read and address all open PR review comments,",
110	      "   then convert the PR from draft back to ready-for-review.",
111	      "",
112	      "Complete all steps without stopping or asking for confirmation.",
113	    ],
114	    modelSection(implementationModel),
115	    [
116	      "## Rules",
117	      "",
118	      "- Do not ask clarifying questions.",
119	      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
120	      "- If you are stuck and cannot proceed, stop gracefully without opening new PRs.",
121	    ],
122	  );
123	}
124	
125	// ── Public API ────────────────────────────────────────────────────────────────
126	
127	export async function dispatchOneReview(
128	  opts: DispatchOneReviewOptions,
129	): Promise<DraftReviewOutcome> {
130	  const {
131	    workspaceRoot,
132	    featureId,
133	    taskId,
134	    taskBranch,
135	    implRepoRoot,
136	    implRepoUrl,
137	    gitAuthorEmail,
138	    gitAuthorName = gitAuthorEmail,
139	    sshKeyPath,
140	    workflowLocalPath,
141	    maxTurns,
142	    maxTokens,
143	    logSinkEnabled,
144	    implementationModel,
145	    workspaceId,
146	    githubToken,
147	    emit,
148	  } = opts;
149	
150	  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
151	  const now = new Date().toISOString();
152	
153	  // ── 1. Checkout and reset task branch in management repo ──────────────────────
154	  try {
155	    execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });
156	    execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
157	    execSync(`git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`, { env, stdio: "pipe" });
158	  } catch (e) {
159	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
160	    return "claim_lost";
161	  }
162	
163	  // ── 2. Read task and guard against duplicate claims ───────────────────────────
164	  let task: Task;
165	  try {
166	    task = readTask(workspaceRoot, featureId, taskId);
167	  } catch (e) {
168	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
169	    return "claim_lost";
170	  }
171	
172	  const lastEntry = task.log[task.log.length - 1];
173	  if (lastEntry?.action === "review_started") {
174	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: "last log entry is review_started" });
175	    return "claim_lost";
176	  }
177	
178	  const REVIEW_CYCLE_ACTIONS = new Set(["review_started", "comments_addressed"]);
179	  const MAX_REVIEW_CYCLES = 3;
180	  let consecutiveReviewCycles = 0;
181	  for (let i = task.log.length - 1; i >= 0; i--) {
182	    if (!REVIEW_CYCLE_ACTIONS.has(task.log[i].action)) break;
183	    if (task.log[i].action === "review_started") consecutiveReviewCycles++;
184	  }
185	  if (consecutiveReviewCycles >= MAX_REVIEW_CYCLES) {
186	    emit({ type: "review_loop_detected", task_id: taskId, feature_id: featureId });
187	    return "claim_lost";
188	  }
189	
190	  // ── 3. Write review_started log entry and push (first-push-wins) ──────────────
191	  task.log.push({ action: "review_started", by: gitAuthorEmail, at: now, note: "Review dispatch claimed." });
192	  task.execution.last_updated_by = gitAuthorEmail;
193	  task.execution.last_updated_at = now;
194	  writeTask(workspaceRoot, featureId, task);
195	
196	  const relPath = taskYamlRelPath(featureId, taskId);
197	  try {
198	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
199	    execSync(`git -C "${workspaceRoot}" commit -m "chore(${taskId}): review_started — claim"`, { env, stdio: "pipe" });
200	  } catch (e) {
201	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: String(e) });
202	    return "claim_lost";
203	  }
204	
205	  const claimPush = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
206	    env, encoding: "utf-8",
207	  });
208	  if (claimPush.status !== 0) {
209	    emit({ type: "review_claim_lost", task_id: taskId, feature_id: featureId, details: claimPush.stderr });
210	    return "claim_lost";
211	  }
212	
213	  emit({ type: "review_dispatching", task_id: taskId, feature_id: featureId, pr_url: task.pr.url });
214	
215	  // ── 4. Build review briefing and run executor ─────────────────────────────────
216	  const reviewBriefing = generateReviewBriefing({
217	    taskId,
218	    featureId,
219	    taskTitle: task.title,
220	    taskBranch,
221	    taskRepo: task.repo,
222	    taskRepoRoot: implRepoRoot,
223	    workspaceRoot,
224	    prUrl: task.pr.url,
225	    gitAuthorEmail,
226	    gitAuthorName,
227	    implementationModel,
228	  });
229	
230	  const { briefingPath } = writeBriefing({ taskId, briefingContent: reviewBriefing });
231	
232	  const resultPath = join(tmpdir(), `review-result-${taskId}.json`);
233	
234	  const input: ExecutorInput = {
235	    taskId,
236	    featureId,
237	    workspaceId,
238	    taskRepoUrl: implRepoUrl,
239	    taskRepoBranch: taskBranch,
240	    taskRepoPath: implRepoRoot,
241	    briefingPath,
242	    resultPath,
243	    budgetTokens: maxTokens,
244	    sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
245	    githubToken,
246	  };
247	
248	  const reviewAdapter = new SubProcessAdapter({
249	    extraEnv: {
250	      WORKSPACE_ROOT: workspaceRoot,
251	      TASK_BRANCH: taskBranch,
252	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
253	      GIT_AUTHOR_NAME: gitAuthorName,
254	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
255	      MAX_TURNS: String(maxTurns),
256	      LOG_SINK_ENABLED: logSinkEnabled ? "1" : "0",
257	    },
258	  });
259	
260	  const runResult = await reviewAdapter.run(input);
261	
262	  emit({
263	    type: "review_dispatch_complete",
264	    task_id: taskId,
265	    feature_id: featureId,
266	    outcome: runResult.terminal_status,
267	  });
268	
269	  return "dispatched";
270	}
271	
272	export async function handleDraftReviews(
273	  opts: HandleDraftReviewsOptions,
274	): Promise<void> {
275	  const {
276	    prResults,
277	    workspaceRoot,
278	    resolveImplRepoRoot,
279	    resolveImplRepoUrl,
280	    resolveTaskRepoId,
281	    resolveImplementationModel,
282	    gitAuthorEmail,
283	    gitAuthorName,
284	    sshKeyPath,
285	    workflowLocalPath,
286	    maxTurns,
287	    maxTokens,
288	    logSinkEnabled,
289	    workspaceId,
290	    githubToken,
291	    emit,
292	  } = opts;
293	
294	  const draftTasks = prResults.filter((r) => r.hasOpenComments === true);
295	
296	  for (const result of draftTasks) {
297	    const { taskId, featureId } = result;
298	
299	    let repoId: string;
300	    try {
301	      repoId = resolveTaskRepoId(featureId, taskId);
302	    } catch (e) {
303	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
304	      continue;
305	    }
306	
307	    let implRepoRoot: string;
308	    let implRepoUrl: string;
309	    try {
310	      implRepoRoot = resolveImplRepoRoot(repoId);
311	      implRepoUrl = resolveImplRepoUrl(repoId);
312	    } catch (e) {
313	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
314	      continue;
315	    }
316	
317	    let implementationModel: string;
318	    try {
319	      implementationModel = resolveImplementationModel(featureId, taskId);
320	    } catch (e) {
321	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
322	      continue;
323	    }
324	
325	    const taskBranch = `feature/${featureId}-${taskId}`;
326	
327	    try {
328	      await dispatchOneReview({
329	        workspaceRoot,
330	        featureId,
331	        taskId,
332	        taskBranch,
333	        implRepoRoot,
334	        implRepoUrl,
335	        gitAuthorEmail,
336	        gitAuthorName,
337	        sshKeyPath,
338	        workflowLocalPath,
339	        maxTurns,
340	        maxTokens,
341	        logSinkEnabled,
342	        implementationModel,
343	        workspaceId,
344	        githubToken,
345	        emit,
346	      });
347	    } catch (e) {
348	      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
349	    }
350	  }
351	}
