101	/**
102	 * Commit and push the updated task YAML to the management repo task branch.
103	 * Non-fatal: logs errors via emit but does not throw.
104	 */
105	function commitAndPushTaskYaml(
106	  workspaceRoot: string,
107	  featureId: string,
108	  taskId: string,
109	  taskBranch: string,
110	  commitMessage: string,
111	  env: NodeJS.ProcessEnv,
112	): void {
113	  const relPath = taskYamlRelPath(featureId, taskId);
114	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
115	    env,
116	    stdio: "pipe",
117	  });
118	  execSync(
119	    `git -C "${workspaceRoot}" commit -m "${commitMessage}"`,
120	    { env, stdio: "pipe" },
121	  );
122	  execSync(
123	    `git -C "${workspaceRoot}" push origin "${taskBranch}"`,
124	    { env, stdio: "pipe" },
125	  );
126	}
