128	/**
129	 * Return all files that currently have conflict markers via `git diff --name-only`.
130	 * Falls back to an empty array on error.
131	 */
132	function listConflictedFiles(
133	  implRepoRoot: string,
134	  env: NodeJS.ProcessEnv,
135	): string[] {
136	  try {
137	    const output = execSync(
138	      `git -C "${implRepoRoot}" diff --name-only --diff-filter=U`,
139	      { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
140	    ).trim();
141	    return output ? output.split("\n") : [];
142	  } catch {
143	    return [];
144	  }
145	}
