147	/**
148	 * Return the set of files the agent has touched on this branch relative to
149	 * origin/<baseBranch>. Uses `git diff --name-only origin/<base>...HEAD`.
150	 * Falls back to an empty Set on error.
151	 */
152	function listAgentAuthoredFiles(
153	  implRepoRoot: string,
154	  baseBranch: string,
155	  env: NodeJS.ProcessEnv,
156	): Set<string> {
157	  try {
158	    const output = execSync(
159	      `git -C "${implRepoRoot}" diff --name-only origin/${baseBranch}...HEAD`,
160	      { env, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
161	    ).trim();
162	    return new Set(output ? output.split("\n") : []);
163	  } catch {
164	    return new Set();
165	  }
166	}
