168	/**
169	 * Build the prompt to send to Claude for resolving conflict markers.
170	 * For dependency manifest files, instruct a union merge.
171	 * For other files, instruct preservation of all functionality from both sides.
172	 */
173	function buildConflictResolutionPrompt(
174	  implRepoRoot: string,
175	  baseBranch: string,
176	  conflictedFiles: string[],
177	): string {
178	  const depFiles = new Set([
179	    "pyproject.toml",
180	    "requirements.txt",
181	    "package.json",
182	    "go.mod",
183	    "Cargo.toml",
184	  ]);
185	
186	  const fileInstructions = conflictedFiles
187	    .map((f) => {
188	      const basename = f.split("/").pop() ?? f;
189	      if (depFiles.has(basename)) {
190	        return `- ${f}: dependency manifest — take the UNION of both sides (include all packages/versions from both HEAD and ${baseBranch}, keeping the higher version where there are conflicts)`;
191	      }
192	      return `- ${f}: preserve ALL functionality from both sides; do not drop any code`;
193	    })
194	    .join("\n");
195	
196	  return (
197	    `You are resolving git merge conflicts after a rebase in the repository at ${implRepoRoot}.\n` +
198	    `The following files contain conflict markers (<<<<<<<, =======, >>>>>>>):\n\n` +
199	    fileInstructions +
200	    `\n\nFor each file:\n` +
201	    `1. Read the file contents (which include conflict markers).\n` +
202	    `2. Resolve the conflict markers according to the instructions above.\n` +
203	    `3. Write the fully resolved content back to disk.\n\n` +
204	    `IMPORTANT:\n` +
205	    `- Do NOT run git add or git commit — only write the resolved file contents.\n` +
206	    `- Do NOT modify any files that are not listed above.\n` +
207	    `- After writing all files, respond with a brief summary of what was resolved.`
208	  );
209	}
