211	/**
212	 * Default implementation: spawns Claude CLI to resolve conflict markers.
213	 * Streams stdout/stderr to process.stdout/stderr.
214	 * Returns true if the process exits with code 0.
215	 */
216	async function defaultInvokeClaudeForResolution(
217	  prompt: string,
218	  cwd: string,
219	  env: NodeJS.ProcessEnv,
220	): Promise<boolean> {
221	  return new Promise((resolve) => {
222	    const child = spawn(
223	      "claude",
224	      [
225	        "-p",
226	        prompt,
227	        "--max-turns",
228	        "10",
229	        "--output-format",
230	        "stream-json",
231	        "--verbose",
232	        "--dangerously-skip-permissions",
233	      ],
234	      { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
235	    );
236	
237	    child.stdout.pipe(process.stdout);
238	    child.stderr.pipe(process.stderr);
239	
240	    child.on("close", (code) => {
241	      resolve(code === 0);
242	    });
243	
244	    child.on("error", () => {
245	      resolve(false);
246	    });
247	  });
248	}
