315	    note: `Rebase claimed; targeting origin/${implBaseBranch}.`,
316	  };
317	
318	  task.conflict_state = "resolving";
319	  task.rebase_log = [...(task.rebase_log ?? []), startedEntry];
320	  task.execution.last_updated_by = gitAuthorEmail;
321	  task.execution.last_updated_at = now;
322	
323	  writeTask(workspaceRoot, featureId, task);
324	
325	  // First-push-wins: if the push is rejected, another agent got there first.
326	  const relPath = taskYamlRelPath(featureId, taskId);
327	  execSync(`git -C "${workspaceRoot}" add "${relPath}"`, {
328	    env,
329	    stdio: "pipe",
330	  });
331	  execSync(
332	    `git -C "${workspaceRoot}" commit -m "chore(${taskId}): rebase_started — claim"`,
333	    { env, stdio: "pipe" },
334	  );
335	
336	  const claimPush = spawnSync(
337	    "git",
338	    ["-C", workspaceRoot, "push", "origin", taskBranch],
339	    { env, encoding: "utf-8" },
340	  );
341	
342	  if (claimPush.status !== 0) {
343	    emit({
344	      type: "rebase_claim_lost",
345	      task_id: taskId,
346	      feature_id: featureId,
347	      details: `Push rejected — another agent claimed the rebase first. stderr: ${claimPush.stderr}`,
348	    });
349	    return "claim_lost";
350	  }
351	
352	  // ── 3. Rebase in the implementation repo ─────────────────────────────────────
353	  try {
354	    execSync(`git -C "${implRepoRoot}" fetch origin`, { env, stdio: "pipe" });
355	  } catch (e) {
356	    emit({
357	      type: "rebase_blocked",
358	      task_id: taskId,
359	      feature_id: featureId,
360	      details: `git fetch failed in impl repo: ${String(e)}`,
361	    });
362	    // Can't proceed — abort and mark blocked.
363	    return await handleConflictedRebase(
364	      opts,
365	      task,
366	      env,
367	      [`git fetch failed: ${String(e)}`],
368	    );
369	  }
370	
371	  // Ensure we are on the task branch in the impl repo.
372	  try {
373	    execSync(`git -C "${implRepoRoot}" checkout "${taskBranch}"`, {
374	      env,
375	      stdio: "pipe",
376	    });
377	    execSync(
378	      `git -C "${implRepoRoot}" reset --hard "origin/${taskBranch}"`,
379	      { env, stdio: "pipe" },
380	    );
381	  } catch (e) {
382	    emit({
383	      type: "rebase_blocked",
384	      task_id: taskId,
385	      feature_id: featureId,
386	      details: `Failed to checkout impl branch ${taskBranch}: ${String(e)}`,
387	    });
388	    return await handleConflictedRebase(opts, task, env, [`checkout failed: ${String(e)}`]);
389	  }
390	
391	  // Capture agent-authored files BEFORE the rebase so we can compare later.
392	  const agentFiles = listAgentAuthoredFiles(implRepoRoot, implBaseBranch, env);
393	
394	  // Abort any in-progress rebase before starting a new one.
395	  spawnSync("git", ["-C", implRepoRoot, "rebase", "--abort"], {
396	    env,
397	    encoding: "utf-8",
398	  });
399	
400	  const rebaseResult = spawnSync(
401	    "git",
402	    ["-C", implRepoRoot, "rebase", `origin/${implBaseBranch}`],
403	    { env, encoding: "utf-8" },
404	  );
405	
406	  if (rebaseResult.status === 0) {
407	    // ── 4a. Clean rebase ────────────────────────────────────────────────────────
408	    return await handleCleanRebase(opts, task, env);
409	  } else {
410	    // ── 4b. Conflicted rebase — three-tier logic ────────────────────────────────
411	    const conflictedFiles = listConflictedFiles(implRepoRoot, env);
412	    const nonAuthoredConflicts = conflictedFiles.filter(
413	      (f) => !agentFiles.has(f),
414	    );
415	
416	    if (conflictedFiles.length > 0 && nonAuthoredConflicts.length === 0) {
417	      // All conflicts are in agent-authored files — attempt Claude resolution.
418	      // A multi-commit rebase may stop at several commits in sequence, so we
419	      // loop: resolve → continue → check for new conflicts → resolve again.
420	      const MAX_RESOLUTION_ROUNDS = 10;
421	      const invoker =
422	        opts.invokeClaudeForResolution ?? defaultInvokeClaudeForResolution;
423	      const allResolvedFiles: string[] = [];
424	      let currentConflicts = conflictedFiles;
425	      let roundsFailed = false;
426	
427	      try {
428	        for (let round = 0; round < MAX_RESOLUTION_ROUNDS; round++) {
429	          emit({
430	            type: "rebase_resolve_attempt",
431	            task_id: taskId,
432	            feature_id: featureId,
433	            conflicted_files: currentConflicts,
434	            round,
435	          });
436	
437	          const prompt = buildConflictResolutionPrompt(
438	            implRepoRoot,
439	            implBaseBranch,
440	            currentConflicts,
441	          );
442	          const resolved = await invoker(prompt, implRepoRoot, env);
443	          if (!resolved) {
444	            roundsFailed = true;
445	            break;
446	          }
447	
448	          allResolvedFiles.push(...currentConflicts);
449	          execSync(`git -C "${implRepoRoot}" add -A`, { env, stdio: "pipe" });
450	          const continueResult = spawnSync(
451	            "git",
452	            ["-C", implRepoRoot, "rebase", "--continue"],
453	            {
454	              env: { ...env, GIT_EDITOR: "true", GIT_SEQUENCE_EDITOR: "true" },
455	              encoding: "utf-8",
456	            },
457	          );
458	
459	          if (continueResult.status === 0) {
460	            // Rebase fully complete.
461	            emit({
462	              type: "rebase_resolved_by_agent",
463	              task_id: taskId,
464	              feature_id: featureId,
465	              conflicted_files: allResolvedFiles,
466	              rounds: round + 1,
467	            });
468	            const resolvedAt = new Date().toISOString();
469	            task.rebase_log = [
470	              ...(task.rebase_log ?? []),
471	              {
472	                at: resolvedAt,
473	                action: "rebase_resolved_by_agent",
474	                by: gitAuthorEmail,
475	                note: `Claude resolved conflict markers in: ${allResolvedFiles.join(", ")} over ${round + 1} round(s); rebase continued cleanly.`,
476	              },
477	            ];
478	            return await handleCleanRebase(opts, task, env);
479	          }
480	
481	          // continue exited non-zero — check if there are new conflicts from
482	          // the next commit in the rebase sequence.
483	          const nextConflicts = listConflictedFiles(implRepoRoot, env);
484	          const nextNonAuthored = nextConflicts.filter((f) => !agentFiles.has(f));
485	          if (nextConflicts.length === 0 || nextNonAuthored.length > 0) {
486	            // Either no new conflict files (unexpected continue failure) or a
487	            // non-agent file appeared — fall through to block.
488	            roundsFailed = true;
489	            break;
490	          }
491	          // Cycle detection: if the same files are still conflicted after
492	          // Claude's resolution pass, the resolution didn't actually work
493	          // (e.g. Claude left conflict markers intact). Break to avoid looping
494	          // on the same files up to MAX_RESOLUTION_ROUNDS.
495	          const nextKey = [...nextConflicts].sort().join(",");
496	          const prevKey = [...currentConflicts].sort().join(",");
497	          if (nextKey === prevKey) {
498	            roundsFailed = true;
499	            break;
500	          }
501	          currentConflicts = nextConflicts;
502	        }
503	      } catch {
504	        roundsFailed = true;
505	      }
506	
507	      if (roundsFailed || allResolvedFiles.length === 0) {
508	        emit({
509	          type: "rebase_resolve_failed",
510	          task_id: taskId,
511	          feature_id: featureId,
512	          conflicted_files: currentConflicts,
513	        });
514	      } else {
515	        // Exceeded MAX_RESOLUTION_ROUNDS with no clean finish.
516	        emit({
517	          type: "rebase_resolve_failed",
518	          task_id: taskId,
519	          feature_id: featureId,
520	          conflicted_files: currentConflicts,
521	          note: `Exceeded ${MAX_RESOLUTION_ROUNDS} resolution rounds`,
522	        });
523	      }
524	    }
525	
526	    return await handleConflictedRebase(opts, task, env, conflictedFiles);
527	  }
528	}
529	
530	// ── Clean rebase handler ──────────────────────────────────────────────────────
531	
532	async function handleCleanRebase(
533	  opts: AutoRebaseOptions,
534	  task: Task,
535	  env: NodeJS.ProcessEnv,
536	): Promise<AutoRebaseOutcome> {
537	  const {
538	    workspaceRoot,
539	    featureId,
540	    taskId,
541	    taskBranch,
542	    implRepoRoot,
543	    gitAuthorEmail,
544	    emit,
545	  } = opts;
546	
547	  // Force-push the impl branch.
548	  const pushResult = spawnSync(
549	    "git",
550	    ["-C", implRepoRoot, "push", "--force-with-lease", "origin", taskBranch],
551	    { env, encoding: "utf-8" },
552	  );
553	
554	  if (pushResult.status !== 0) {
555	    emit({
556	      type: "rebase_blocked",
557	      task_id: taskId,
558	      feature_id: featureId,
559	      details: `force-with-lease push failed after clean rebase: ${pushResult.stderr}`,
560	    });
561	    // Rare — treat as a recoverable blocked state.
562	    return await handleConflictedRebase(
563	      opts,
564	      task,
565	      env,
566	      [`force-push failed: ${pushResult.stderr}`],
567	    );
568	  }
569	
570	  // Update task YAML with resolved state.
571	  const completedAt = new Date().toISOString();
572	  const completedEntry: RebaseLogEntry = {
573	    at: completedAt,
574	    action: "rebase_completed",
575	    by: gitAuthorEmail,
576	    note: "Rebase completed cleanly; impl branch force-pushed.",
577	  };
578	
579	  task.conflict_state = "resolved";
580	  task.rebase_log = [...(task.rebase_log ?? []), completedEntry];
581	  task.execution.last_updated_by = gitAuthorEmail;
582	  task.execution.last_updated_at = completedAt;
583	
584	  writeTask(workspaceRoot, featureId, task);
585	
586	  try {
587	    commitAndPushTaskYaml(
588	      workspaceRoot,
589	      featureId,
590	      taskId,
591	      taskBranch,
592	      `chore(${taskId}): rebase_completed — conflict_state resolved`,
593	      env,
594	    );
595	  } catch (e) {
596	    emit({
597	      type: "rebase_completed",
598	      task_id: taskId,
599	      feature_id: featureId,
600	      note: "Rebase clean but management repo push failed — YAML may be stale.",
601	      details: String(e),
602	    });
603	    return "rebase_completed";
604	  }
605	
606	  emit({
607	    type: "rebase_completed",
608	    task_id: taskId,
609	    feature_id: featureId,
610	  });
611	
612	  return "rebase_completed";
613	}
614	
615	// ── Conflicted rebase handler ─────────────────────────────────────────────────
616	
617	async function handleConflictedRebase(
618	  opts: AutoRebaseOptions,
619	  task: Task,
620	  env: NodeJS.ProcessEnv,
621	  conflictedFiles: string[],
622	): Promise<AutoRebaseOutcome> {
623	  const {
624	    workspaceRoot,
625	    featureId,
626	    taskId,
627	    taskBranch,
628	    implRepoRoot,
629	    gitAuthorEmail,
630	    emit,
631	  } = opts;
632	
633	  // Abort any ongoing rebase so git is in a clean-enough state.
634	  spawnSync("git", ["-C", implRepoRoot, "rebase", "--abort"], {
635	    env,
636	    encoding: "utf-8",
637	  });
638	
639	  // Stage everything (including conflict markers) and commit.
640	  spawnSync("git", ["-C", implRepoRoot, "add", "-A"], {
641	    env,
642	    encoding: "utf-8",
643	  });
644	
645	  const conflictSummary =
646	    conflictedFiles.length > 0
647	      ? conflictedFiles.join(", ")
648	      : "unknown files";
649	
650	  const commitResult = spawnSync(
651	    "git",
652	    [
653	      "-C",
654	      implRepoRoot,
655	      "commit",
656	      "-m",
657	      `wip(${taskId}): conflict markers after failed rebase — ${conflictSummary}`,
658	    ],
659	    { env, encoding: "utf-8" },
660	  );
661	
662	  // Push even if commit was a no-op (nothing staged).
663	  if (commitResult.status === 0) {
664	    spawnSync(
665	      "git",
666	      ["-C", implRepoRoot, "push", "origin", taskBranch],
667	      { env, encoding: "utf-8" },
668	    );
669	  }
670	
671	  // Build the blocked_suggestion with file:line pointers.
672	  const blockedNote =
673	    conflictedFiles.length > 0
674	      ? `Unresolvable merge conflicts in: ${conflictedFiles.join("; ")}. Manual resolution required.`
675	      : "Merge conflicts detected during rebase. Manual resolution required.";
676	
677	  const blockedAt = new Date().toISOString();
678	  const blockedEntry: RebaseLogEntry = {
679	    at: blockedAt,
680	    action: "rebase_blocked",
681	    by: gitAuthorEmail,
682	    note: blockedNote,
683	  };
684	
685	  task.status = "blocked";
686	  task.blocked_reason = "pr_conflict";
687	  // "resolved" signals that the conflict has been surfaced to the branch and
688	  // is visible in the PR — not that it has been fixed. See technical-design.md.
689	  task.conflict_state = "resolved";
690	  task.rebase_log = [...(task.rebase_log ?? []), blockedEntry];
691	  task.execution.last_updated_by = gitAuthorEmail;
692	  task.execution.last_updated_at = blockedAt;
693	  task.execution.suggested_next_step =
694	    "Manually resolve the conflicts listed in blocked_reason detail, then set status back to in_review.";
695	  task.log.push({
696	    action: "blocked",
697	    by: gitAuthorEmail,
698	    at: blockedAt,
699	    note: blockedNote,
700	  });
701	
702	  writeTask(workspaceRoot, featureId, task);
703	
704	  try {
705	    commitAndPushTaskYaml(
706	      workspaceRoot,
707	      featureId,
708	      taskId,
709	      taskBranch,
710	      `chore(${taskId}): rebase_blocked — pr_conflict`,
711	      env,
712	    );
713	  } catch (e) {
714	    emit({
715	      type: "rebase_blocked",
716	      task_id: taskId,
717	      feature_id: featureId,
718	      conflicted_files: conflictedFiles,
719	      note: "Management repo YAML push failed — YAML may be stale.",
720	      details: String(e),
721	    });
722	    return "rebase_blocked";
723	  }
724	
725	  emit({
726	    type: "rebase_blocked",
727	    task_id: taskId,
728	    feature_id: featureId,
729	    conflicted_files: conflictedFiles,
730	  });
731	
732	  return "rebase_blocked";
733	}
734	
735	// ── Cycle-level orchestrator ──────────────────────────────────────────────────
736	
737	export interface HandleMergeConflictsOptions {
738	  /** Results from checkInReviewPrs — only those with mergeable === false are processed. */
739	  prResults: PrStatusResult[];
740	  /** Absolute path to the management (workspace) repo root — keyed by workspaceRoot. */
741	  workspaceRoot: string;
742	  /** Resolve the impl repo root for a given repo ID (from workspace.yaml). */
743	  resolveImplRepoRoot: (repoId: string) => string;
744	  /** Resolve the impl base branch for a given repo ID (from workspace.yaml). */
745	  resolveImplBaseBranch: (repoId: string) => string;
746	  /** Resolve the task's repo ID from the task YAML. */
747	  resolveTaskRepoId: (featureId: string, taskId: string) => string;
748	  /** GIT_AUTHOR_EMAIL for commits and log entries. */
749	  gitAuthorEmail: string;
750	  /** GIT_AUTHOR_NAME for commits. Defaults to gitAuthorEmail. */
751	  gitAuthorName?: string;
752	  /** SSH private key path for git push operations. */
753	  sshKeyPath?: string;
754	  /** Structured event emitter for observability. */
755	  emit: (event: Record<string, unknown>) => void;
756	}
757	
758	/**
759	 * Iterate T2 poll results where `mergeable === false` and run autoRebase for each.
760	 * Called from `runOneCycle` in main.ts after the ready-task pass.
761	 */
762	export async function handleMergeConflicts(
763	  opts: HandleMergeConflictsOptions,
764	): Promise<void> {
765	  const {
766	    prResults,
767	    workspaceRoot,
768	    resolveImplRepoRoot,
769	    resolveImplBaseBranch,
770	    resolveTaskRepoId,
771	    gitAuthorEmail,
772	    gitAuthorName,
773	    sshKeyPath,
774	    emit,
775	  } = opts;
776	
777	  const conflicted = prResults.filter((r) => r.mergeable === false);
778	
779	  // Only process one conflicted task per impl repo per cycle to prevent
780	  // concurrent git rebase operations on the same on-disk clone.
781	  const processedImplRoots = new Set<string>();
782	
783	  for (const result of conflicted) {
784	    const { taskId, featureId } = result;
785	
786	    let repoId: string;
787	    try {
788	      repoId = resolveTaskRepoId(featureId, taskId);
789	    } catch (e) {
790	      emit({
791	        type: "rebase_blocked",
792	        task_id: taskId,
793	        feature_id: featureId,
794	        details: `Cannot resolve repo ID: ${String(e)}`,
795	      });
796	      continue;
797	    }
798	
799	    let implRepoRoot: string;
800	    let implBaseBranch: string;
801	    try {
802	      implRepoRoot = resolveImplRepoRoot(repoId);
803	      implBaseBranch = resolveImplBaseBranch(repoId);
804	    } catch (e) {
805	      emit({
806	        type: "rebase_blocked",
807	        task_id: taskId,
808	        feature_id: featureId,
809	        details: `Cannot resolve impl repo path or base branch: ${String(e)}`,
810	      });
811	      continue;
812	    }
813	
814	    if (processedImplRoots.has(implRepoRoot)) {
815	      emit({
816	        type: "rebase_skipped_concurrent",
817	        task_id: taskId,
818	        feature_id: featureId,
819	        details: `impl repo ${implRepoRoot} already has a rebase in progress this cycle — skipping to prevent concurrent git operations`,
820	      });
821	      continue;
822	    }
823	    processedImplRoots.add(implRepoRoot);
824	
825	    const taskBranch = `feature/${featureId}-${taskId}`;
826	
827	    try {
828	      await autoRebase({
829	        workspaceRoot,
830	        featureId,
831	        taskId,
832	        taskBranch,
833	        implRepoRoot,
834	        implBaseBranch,
835	        gitAuthorEmail,
836	        gitAuthorName,
837	        sshKeyPath,
838	        emit,
839	      });
840	    } catch (e) {
841	      emit({
842	        type: "rebase_blocked",
843	        task_id: taskId,
844	        feature_id: featureId,
845	        details: `Unexpected error in autoRebase: ${String(e)}`,
846	      });
847	    }
848	  }
849	}
