/**
 * GitWorkflowStateAdapter — WorkflowStatePort adapter.
 *
 * Reads and writes task YAMLs from the git-managed management workspace.
 * Git remains authoritative for workflow state in every profile.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { WorkflowStatePort, ExecutorHandle } from "@workflow/runtime-abi";
import { taskYamlAbsPath, taskYamlRelPath } from "../../paths.js";
import { buildGitEnv } from "../../git-env.js";

export interface GitWorkflowStateAdapterOpts {
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

export class GitWorkflowStateAdapter implements WorkflowStatePort {
  private readonly gitAuthorEmail: string;
  private readonly gitAuthorName: string;
  private readonly sshKeyPath: string | undefined;

  constructor(opts: GitWorkflowStateAdapterOpts) {
    this.gitAuthorEmail = opts.gitAuthorEmail;
    this.gitAuthorName = opts.gitAuthorName ?? opts.gitAuthorEmail;
    this.sshKeyPath = opts.sshKeyPath;
  }

  async readTask(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
  ): Promise<Record<string, unknown>> {
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    return parseYaml(readFileSync(yamlPath, "utf-8")) as Record<string, unknown>;
  }

  async writeTask(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    data: Record<string, unknown>,
  ): Promise<void> {
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    writeFileSync(yamlPath, yamlStringify(data), "utf-8");
  }

  async appendLog(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    entry: Record<string, unknown>,
  ): Promise<void> {
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    const task = parseYaml(readFileSync(yamlPath, "utf-8")) as {
      log: unknown[];
      execution: { last_updated_by: string | null; last_updated_at: string | null };
    };
    const at = (entry.at as string | undefined) ?? new Date().toISOString();
    task.log.push({ ...entry, at });
    task.execution.last_updated_by = this.gitAuthorEmail;
    task.execution.last_updated_at = at;
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  }

  async persistHandle(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    handle: ExecutorHandle,
  ): Promise<void> {
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
    const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Record<string, unknown>;
    task.execution_handle = handle;
    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
  }

  /** Commit and push the task YAML to a branch. Non-throwing — returns error or undefined. */
  commitAndPush(
    workspaceRoot: string,
    featureId: string,
    taskId: string,
    taskBranch: string,
    commitMsg: string,
  ): string | undefined {
    const relPath = taskYamlRelPath(featureId, taskId);
    const env = buildGitEnv(this.sshKeyPath, { email: this.gitAuthorEmail, name: this.gitAuthorName });
    try {
      execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
      execSync(`git -C "${workspaceRoot}" commit -m "${commitMsg}"`, { env, stdio: "pipe" });
    } catch (e) {
      return `git add/commit failed: ${String(e)}`;
    }
    try {
      execSync(
        `git -C "${workspaceRoot}" pull --rebase origin "${taskBranch}"`,
        { env, stdio: "pipe" },
      );
    } catch (e) {
      return `git pull --rebase failed: ${String(e)}`;
    }
    const push = spawnSync(
      "git",
      ["-C", workspaceRoot, "push", "origin", taskBranch],
      { env, encoding: "utf-8" },
    );
    if (push.status !== 0) {
      return `git push failed: ${push.stderr}`;
    }
    return undefined;
  }
}

