        implRepoRoot,
        implRepoUrl,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        workflowLocalPath,
        maxTurns,
        maxTokens,
        logSinkEnabled,
        implementationModel,
        workspaceId,
        githubToken,
        emit,
      });
    } catch (e) {
      emit({ type: "review_dispatch_error", task_id: taskId, feature_id: featureId, details: String(e) });
    }
  }
}

